struct SearchBar: UIViewRepresentable {
  @Binding var text: String
  var onCommit: () -> Void

  func makeCoordinator() -> Coordinator { Coordinator(self) }

  func makeUIView(context: Context) -> UISearchBar {
    let bar = UISearchBar()
    bar.delegate = context.coordinator          // the coordinator is the delegate
    return bar
  }

  func updateUIView(_ bar: UISearchBar, context: Context) {
    context.coordinator.parent = self           // the captured copy is stale otherwise
    if bar.text != text {                       // guard: an equal write moves the caret
      bar.text = text
    }
  }

  static func dismantleUIView(_ bar: UISearchBar, coordinator: Coordinator) {
    coordinator.debounce?.cancel()
  }

  final class Coordinator: NSObject, UISearchBarDelegate {
    var parent: SearchBar
    var debounce: Task<Void, Never>?            // stateful work lives here, not in the struct

    init(_ parent: SearchBar) { self.parent = parent }

    func searchBar(_ bar: UISearchBar, textDidChange text: String) {
      parent.text = text                        // upward: writes the SwiftUI binding
    }

    func searchBarSearchButtonClicked(_ bar: UISearchBar) {
      parent.onCommit()
    }
  }
}

