// One value, one branch per state
@Observable final class FeedModel {
  enum ViewState: Equatable {
    case loading
    case loaded(items: [Item], isRefreshing: Bool)
    case empty
    case failed(String)
  }

  private(set) var state: ViewState = .loading

  func load() async {
    if case .loaded(let items, _) = state {
      state = .loaded(items: items, isRefreshing: true)   // keep the list on screen
    } else {
      state = .loading
    }
    do {
      let items = try await api.feed()
      state = items.isEmpty ? .empty : .loaded(items: items, isRefreshing: false)
    } catch {
      state = .failed(error.localizedDescription)
    }
  }
}

struct FeedView: View {
  @State private var model = FeedModel()

  var body: some View {
    switch model.state {              // a new case will not compile until it is drawn
    case .loading:
      ProgressView()
    case .loaded(let items, let isRefreshing):
      List(items) { Text($0.title) }
        .overlay(alignment: .top) { if isRefreshing { ProgressView() } }
        .refreshable { await model.load() }
    case .empty:
      ContentUnavailableView("No posts", systemImage: "tray")
    case .failed(let message):
      ContentUnavailableView {
        Text("Could not load")
      } description: {
        Text(message)
      } actions: {
        Button("Retry") { Task { await model.load() } }
      }
    }
  }
}

// Roughly what @Observable expands to
final class Model: Observable {
  @ObservationIgnored private var _title = ""
  @ObservationIgnored private let registrar = ObservationRegistrar()

  var title: String {
    get {
      registrar.access(self, keyPath: \.title)          // records the read
      return _title
    }
    set {
      registrar.withMutation(of: self, keyPath: \.title) {  // notifies observers
        _title = newValue
      }
    }
  }
}

// Tracking outside SwiftUI is one-shot: re-arm it or you hear exactly one change
func observeTitle(_ model: Model) {
  withObservationTracking {
    _ = model.title
  } onChange: {
    // runs BEFORE the write lands — hop out to read the new value
    Task { @MainActor in observeTitle(model) }
  }
}

