  private(set) var items: [Item] = []
  private(set) var isLoading = false
  private let url = URL(string: "https://example.com/feed")!

  func load() async {
    isLoading = true
    defer { isLoading = false }            // both writes are on the main actor
    do {
      let (data, _) = try await URLSession.shared.data(from: url)  // runs off the actor
      items = try await Self.parse(data)                           // result lands here
    } catch {
      items = []
    }
  }

  func apply(_ items: [Item]) { self.items = items }

  // Heavy CPU work leaves the main actor explicitly
  nonisolated private static func parse(_ data: Data) async throws -> [Item] {
    try JSONDecoder().decode([Item].self, from: data)
  }
}

// Bridging a callback API that cannot be awaited
func legacyLoad(into feed: Feed) {
  LegacyClient.fetch { items in
    Task { @MainActor in feed.apply(items) }
  }
}

